  const app = spawn(EXE, [], {
    env: {
      ...process.env,
      WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS: `--remote-debugging-port=${PORT}`,
      BUSLINK_E2E_EXPORT_DIR: EXPORT_DIR,
